# Bisherige Beträge als benannte Buttons übernehmen, Namen lassen sich in der Verwaltung ändern
DEFAULT_LABELS = {60: "Getränk klein", 110: "Getränk", 450: "Essen"}


def create_buttons(apps, schema_editor):
    Config = apps.get_model("strichliste", "Config")
    DispenseButton = apps.get_model("strichliste", "DispenseButton")
    config = Config.objects.filter(pk=1).first()
    steps = config.dispense_steps if config else "60,110,450"
    for position, cents in enumerate((int(step) for step in steps.split(",") if step.strip()), start=1):
        DispenseButton.objects.create(label=DEFAULT_LABELS.get(cents, "Ausgabe"), cents=cents, position=position)


